INSERT INTO questions (section, topic, difficulty, question_text, option_a, option_b, option_c, option_d, correct_option) VALUES ('verbal', 'Reading Comprehension', 'Medium', '''Critical thinking enables individuals to analyze arguments objectively rather than accepting assertions uncritically.'' Critical thinking involves:', 'Objective analysis of arguments', 'Passive acceptance of statements', 'Emotional decision making', 'Memorizing facts', 'A');
