INSERT INTO questions (section, topic, difficulty, question_text, option_a, option_b, option_c, option_d, correct_option) VALUES ('verbal', 'Reading Comprehension', 'Easy', '''Photosynthesis converts solar light energy into chemical energy stored in glucose.'' Photosynthesis produces chemical energy stored in:', 'Glucose', 'Chlorophyll', 'Oxygen alone', 'Soil', 'A');
