INSERT INTO questions (section, topic, difficulty, question_text, option_a, option_b, option_c, option_d, correct_option) VALUES ('verbal', 'Reading Comprehension', 'Easy', '''Exercise stimulates endorphin release, fostering positive mood and reducing perceived stress.'' Endorphins help by:', 'Fostering positive mood and reducing stress', 'Increasing blood pressure', 'Inducing lethargy', 'Decreasing muscle stamina', 'A');
INSERT INTO questions (section, topic, difficulty, question_text, option_a, option_b, option_c, option_d, correct_option) VALUES ('verbal', 'Reading Comprehension', 'Hard', '''The essay contends that technological ubiquity creates an illusion of interconnectedness while deepening interpersonal alienation.'' The central paradox is:', 'High connectivity coexisting with emotional isolation', 'Tech being too inexpensive', 'Lack of information access', 'Machines replacing teachers', 'A');
