INSERT INTO questions (section, topic, difficulty, question_text, option_a, option_b, option_c, option_d, correct_option) VALUES ('verbal', 'Error Detection', 'Easy', 'Find error part: ''She is junior (A) / than me (B) / in the company (C) / No error (D)''', '(B) than me (should be ''to me'')', '(A)', '(C)', '(D)', 'A');
INSERT INTO questions (section, topic, difficulty, question_text, option_a, option_b, option_c, option_d, correct_option) VALUES ('verbal', 'Error Detection', 'Medium', 'Find error part: ''I would rather (A) / to die (B) / than beg (C) / No error (D)''', '(B) to die (should be bare infinitive ''die'')', '(A)', '(C)', '(D)', 'A');
INSERT INTO questions (section, topic, difficulty, question_text, option_a, option_b, option_c, option_d, correct_option) VALUES ('verbal', 'Error Detection', 'Hard', 'Find error part: ''One of my friends (A) / are visiting (B) / from Canada tomorrow (C) / No error (D)''', '(B) are visiting (should be ''is visiting'')', '(A)', '(C)', '(D)', 'A');
INSERT INTO questions (section, topic, difficulty, question_text, option_a, option_b, option_c, option_d, correct_option) VALUES ('verbal', 'Error Detection', 'Easy', 'Find error part: ''He has been absent (A) / from Monday (B) / last week (C) / No error (D)''', '(B) from Monday (should be ''since Monday'')', '(A)', '(C)', '(D)', 'A');
INSERT INTO questions (section, topic, difficulty, question_text, option_a, option_b, option_c, option_d, correct_option) VALUES ('verbal', 'Error Detection', 'Medium', 'Find error part: ''Neither she nor her sisters (A) / was invited (B) / to the party (C) / No error (D)''', '(B) was invited (verb agrees with nearest subject ''sisters'', needs ''were'')', '(A)', '(C)', '(D)', 'A');
INSERT INTO questions (section, topic, difficulty, question_text, option_a, option_b, option_c, option_d, correct_option) VALUES ('verbal', 'Error Detection', 'Hard', 'Find error part: ''Hardly had she arrived (A) / then the phone (B) / rang loudly (C) / No error (D)''', '(B) then the phone (hardly pairs with ''when'', not ''then'')', '(A)', '(C)', '(D)', 'A');
