-- Smart Placement System - Complete MySQL Database Script
-- Generated with 300+ Verified Realistic MCQs for Placement Preparation

CREATE DATABASE IF NOT EXISTS smart_placement_db CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE smart_placement_db;

-- 1. Users table
CREATE TABLE IF NOT EXISTS users (
    id INT AUTO_INCREMENT PRIMARY KEY,
    username VARCHAR(50) NOT NULL UNIQUE,
    email VARCHAR(100) NOT NULL UNIQUE,
    password_hash VARCHAR(255) NOT NULL,
    avatar VARCHAR(50) DEFAULT 'avatar11.svg',
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
) ENGINE=InnoDB;

-- 2. Questions bank table
CREATE TABLE IF NOT EXISTS questions (
    id INT AUTO_INCREMENT PRIMARY KEY,
    section ENUM('quantitative', 'logical', 'verbal') NOT NULL,
    topic VARCHAR(100) NOT NULL,
    difficulty ENUM('Easy', 'Medium', 'Hard') DEFAULT 'Medium',
    question_text TEXT NOT NULL,
    option_a VARCHAR(255) NOT NULL,
    option_b VARCHAR(255) NOT NULL,
    option_c VARCHAR(255) NOT NULL,
    option_d VARCHAR(255) NOT NULL,
    correct_option CHAR(1) NOT NULL,
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    INDEX idx_section (section)
) ENGINE=InnoDB;

-- 3. Quiz Attempts table
CREATE TABLE IF NOT EXISTS quiz_attempts (
    id INT AUTO_INCREMENT PRIMARY KEY,
    user_id INT NOT NULL,
    section ENUM('quantitative', 'logical', 'verbal') NOT NULL,
    total_questions INT DEFAULT 15,
    attempted_count INT DEFAULT 0,
    correct_count INT DEFAULT 0,
    incorrect_count INT DEFAULT 0,
    score INT DEFAULT 0,
    accuracy DECIMAL(5,2) DEFAULT 0.00,
    total_time_seconds INT DEFAULT 0,
    avg_response_time DECIMAL(5,2) DEFAULT 0.00,
    is_submitted TINYINT(1) DEFAULT 0,
    started_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    submitted_at TIMESTAMP NULL,
    FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE,
    INDEX idx_user_attempt (user_id, section)
) ENGINE=InnoDB;

-- 4. Quiz Responses table
CREATE TABLE IF NOT EXISTS quiz_responses (
    id INT AUTO_INCREMENT PRIMARY KEY,
    attempt_id INT NOT NULL,
    question_id INT NOT NULL,
    question_order INT NOT NULL,
    selected_option CHAR(1) NULL,
    is_correct TINYINT(1) DEFAULT 0,
    response_time_seconds INT DEFAULT 0,
    FOREIGN KEY (attempt_id) REFERENCES quiz_attempts(id) ON DELETE CASCADE,
    FOREIGN KEY (question_id) REFERENCES questions(id) ON DELETE CASCADE,
    INDEX idx_attempt (attempt_id)
) ENGINE=InnoDB;

-- 5. User Question History table (Rotational question tracking)
CREATE TABLE IF NOT EXISTS user_question_history (
    id INT AUTO_INCREMENT PRIMARY KEY,
    user_id INT NOT NULL,
    question_id INT NOT NULL,
    section ENUM('quantitative', 'logical', 'verbal') NOT NULL,
    served_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE,
    FOREIGN KEY (question_id) REFERENCES questions(id) ON DELETE CASCADE,
    INDEX idx_user_sec (user_id, section)
) ENGINE=InnoDB;

-- 6. User Streaks table
CREATE TABLE IF NOT EXISTS user_streaks (
    id INT AUTO_INCREMENT PRIMARY KEY,
    user_id INT NOT NULL UNIQUE,
    current_streak INT DEFAULT 0,
    longest_streak INT DEFAULT 0,
    last_practice_date DATE NULL,
    FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE
) ENGINE=InnoDB;

-- Clear previous questions if any to reload fresh bank
SET FOREIGN_KEY_CHECKS = 0;
TRUNCATE TABLE questions;
SET FOREIGN_KEY_CHECKS = 1;

